 	// Task counts by status
 	interface TaskCounts {
 		ready: number;
 		in_progress: number;
 		pending_review: number;
+		needs_work: number;
 		blocked: number;
 		completed: number;
 	}

 	let counts = $state<TaskCounts>({
 		ready: 0,
 		in_progress: 0,
 		pending_review: 0,
+		needs_work: 0,
 		blocked: 0,
 		completed: 0
 	});

