  1	<script lang="ts">
  2		import { onMount } from 'svelte';
  3		import { goto } from '$app/navigation';
  4		import { base } from '$app/paths';
  5		import { fetchTasks } from '$lib/api';
  6		import { Card, CardContent, CardHeader, CardTitle } from '$lib/components/ui/card';
  7		import { Badge } from '$lib/components/ui/badge';
  8		import { getProjectVersion } from '$lib/stores/project.svelte';
  9	
 10		// AC: @web-dashboard ac-1, ac-2, ac-3
 11		// Task counts by status
 12		interface TaskCounts {
 13			ready: number;
 14			in_progress: number;
 15			pending_review: number;
 16			needs_work: number;
 17			blocked: number;
 18			completed: number;
 19		}
 20	
 21		let counts = $state<TaskCounts>({
 22			ready: 0,
 23			in_progress: 0,
 24			pending_review: 0,
 25			needs_work: 0,
 26			blocked: 0,
 27			completed: 0
 28		});
 29	
 30		let loading = $state(true);
 31	
 32		onMount(async () => {
 33			await loadCounts();
 34		});
 35	
 36		// AC: @multi-directory-daemon ac-27 - Reload data when project changes
 37		$effect(() => {
 38			const version = getProjectVersion();
 39			if (version > 0) {
 40				// Only reload if version has been incremented (not on initial load)
 41				loadCounts();
 42			}
 43		});
 44	
 45		async function loadCounts() {
 46			try {
 47				// Fetch all tasks to compute counts
 48				const response = await fetchTasks({ limit: 1000 });
 49				const tasks = response.items;
 50	
 51				// Compute counts
 52				const newCounts: TaskCounts = {
 53					ready: 0,
 54					in_progress: 0,
 55					pending_review: 0,
 56					needs_work: 0,
 57					blocked: 0,
 58					completed: 0
 59				};
 60	
 61				// Build a set of completed task refs for dependency checking
 62				const completedRefs = new Set(
 63					tasks
 64						.filter((t) => t.status === 'completed')
 65						.flatMap((t) => [t._ulid, ...(t.slugs || [])])
 66				);
 67	
 68				for (const task of tasks) {
 69					if (task.status === 'completed') {
 70						newCounts.completed++;
 71					} else if (task.status === 'in_progress') {
 72						newCounts.in_progress++;
 73					} else if (task.status === 'pending_review') {
 74						newCounts.pending_review++;
 75					} else if (task.status === 'needs_work') {
 76						newCounts.needs_work++;
 77					} else if (task.status === 'blocked') {
 78						newCounts.blocked++;
 79					} else if (task.status === 'pending') {
 80						// Check if blocked by dependencies
 81						const deps = task.depends_on || [];
 82						const hasUnmetDeps = deps.some((dep) => {
 83							// Remove @ prefix if present
 84							const ref = dep.startsWith('@') ? dep.slice(1) : dep;
 85							return !completedRefs.has(ref);
 86						});
 87						if (hasUnmetDeps) {
 88							newCounts.blocked++;
 89						} else {
 90							newCounts.ready++;
 91						}
 92					}
 93				}
 94	
 95				counts = newCounts;
 96			} catch (err) {
 97				console.error('Failed to load task counts:', err);
 98			} finally {
 99				loading = false;
100			}
101		}
102	
103		// AC: @web-dashboard ac-3
104		function navigateToTasks(status: string) {
105			goto(`${base}/tasks?status=${status}`);
106		}
107	
108		// Status display config
109		const statusConfig = [
110			{ key: 'ready', label: 'Ready', color: 'bg-emerald-500', filterStatus: 'pending' },
111			{ key: 'in_progress', label: 'In Progress', color: 'bg-orange-500', filterStatus: 'in_progress' },
112			{
113				key: 'pending_review',
114				label: 'Pending Review',
115				color: 'bg-blue-500',
116				filterStatus: 'pending_review'
117			},
118			{ key: 'needs_work', label: 'Needs Work', color: 'bg-yellow-500', filterStatus: 'needs_work' },
119			{ key: 'blocked', label: 'Blocked', color: 'bg-red-500', filterStatus: 'blocked' },
120			{ key: 'completed', label: 'Completed', color: 'bg-emerald-500', filterStatus: 'completed' }

