 83		async function loadData() {
 84			try {
 85				loading = true;
 86				error = '';
 87				const response = await fetchPlans();
 88				plans = response.items;
 89			} catch (err) {
 90				error = err instanceof Error ? err.message : 'Failed to load plans';
 91			} finally {
