101		// ── Formatting ──
102		function formatDate(dateString: string): string {
103			const date = new Date(dateString);
104			const now = new Date();
105			const diffMs = now.getTime() - date.getTime();
106			const diffMins = Math.floor(diffMs / 60000);
107			const diffHours = Math.floor(diffMs / 3600000);
108			const diffDays = Math.floor(diffMs / 86400000);
109	
110			if (diffMins < 1) return 'just now';
111			if (diffMins < 60) return `${diffMins}m ago`;
112			if (diffHours < 24) return `${diffHours}h ago`;
113			if (diffDays < 7) return `${diffDays}d ago`;
114	
115			return date.toLocaleDateString();
116		}
